{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "MitoQ, a triphenylphosphonium cation with a long lipophilic alkyl chain, was detected at high levels in mouse brain tissue, demonstrating that this class of permanent cations can achieve meaningful CNS access despite unfavorable passive-diffusion properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "FTY720-C2, which shares the octylphenyl-propyl-diol amide scaffold with the query, rapidly entered the brain and reached brain concentrations higher than plasma after IV and oral dosing in mice, showing that this lipophilic scaffold can cross the BBB effectively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "FTY720 and its phosphorylated metabolite crossed the BBB with brain-to-blood ratios greater than 10 in mice, indicating that even charged species related to this scaffold can achieve substantial CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the query has a permanent phosphonium cation, high molecular weight, and low predicted passive permeability, transferable in vivo evidence from the closely related FTY720/FTY720-C2 scaffold and from the triphenylphosphonium-containing MitoQ indicates that this compound class can achieve meaningful brain exposure after systemic administration.",
  "evidence_gaps": [
    "No direct brain or CSF exposure measurement exists for the exact TPP-FTY720 amide query molecule.",
    "Quantitative unbound brain-to-plasma ratio (Kp,uu) and efflux-transporter status are unknown.",
    "Human CNS exposure data for this specific phosphonium conjugate are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

